import React, { useState } from "react";
import {
  Box,
  Typography,
  Button,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Tooltip,
} from "@mui/material";
import { Add, Edit, Delete } from "@mui/icons-material";

const ManageCandidates = () => {
  const [candidates, setCandidates] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [currentCandidate, setCurrentCandidate] = useState({
    id: null,
    name: "",
    bio: "",
    manifesto: "",
    position: "",
    photo: "",
    video: "",
  });

  const handleOpenDialog = (candidate = {
    id: null,
    name: "",
    bio: "",
    manifesto: "",
    position: "",
    photo: "",
    video: "",
  }) => {
    setCurrentCandidate(candidate);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setCurrentCandidate({
      id: null,
      name: "",
      bio: "",
      manifesto: "",
      position: "",
      photo: "",
      video: "",
    });
  };

  const handleSaveCandidate = () => {
    if (currentCandidate.id === null) {
      // Add new candidate
      setCandidates([...candidates, { ...currentCandidate, id: candidates.length + 1 }]);
    } else {
      // Update existing candidate
      setCandidates(candidates.map((candidate) =>
        candidate.id === currentCandidate.id ? currentCandidate : candidate
      ));
    }
    handleCloseDialog();
  };

  const handleDeleteCandidate = (id) => {
    setCandidates(candidates.filter((candidate) => candidate.id !== id));
  };

  return (
    <Box sx={{ p: 4, backgroundColor: "rgba(100, 200, 225, 0.3)", minHeight: "100vh" }}>
      {/* Centered Heading and Button */}
      <Box sx={{ textAlign: "center", mb: 4 }}>
        <Typography variant="h4" fontWeight="bold" mb={2}>
          Manage Candidates
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => handleOpenDialog()}
          sx={{
            bgcolor: "#28a745",
            color: "white",
            "&:hover": { bgcolor: "#218838" },
          }}
        >
          Add New Candidate
        </Button>
      </Box>

      {/* Full-width Table */}
      <TableContainer
        component={Paper}
        sx={{
          borderRadius: "16px",
          boxShadow: 4,
          width: "100%",
          maxHeight: "60vh",
          overflow: "auto",
        }}
      >
        <Table sx={{ minWidth: 650 }}>
          <TableHead>
            <TableRow sx={{ backgroundColor: "#007bff" }}>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Name</TableCell>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Position</TableCell>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Bio</TableCell>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Manifesto</TableCell>
              <TableCell sx={{ color: "white", fontWeight: "bold" }}>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {candidates.map((candidate) => (
              <TableRow key={candidate.id} sx={{ "&:hover": { backgroundColor: "rgba(0, 123, 255, 0.1)" } }}>
                <TableCell>{candidate.name}</TableCell>
                <TableCell>{candidate.position}</TableCell>
                <TableCell>{candidate.bio}</TableCell>
                <TableCell>{candidate.manifesto}</TableCell>
                <TableCell>
                  <Tooltip title="Edit Candidate">
                    <IconButton
                      onClick={() => handleOpenDialog(candidate)}
                      sx={{ color: "#007bff", "&:hover": { color: "#0056b3" } }}
                    >
                      <Edit />
                    </IconButton>
                  </Tooltip>
                  <Tooltip title="Delete Candidate">
                    <IconButton
                      onClick={() => handleDeleteCandidate(candidate.id)}
                      sx={{ color: "#dc3545", "&:hover": { color: "#a71d2a" } }}
                    >
                      <Delete />
                    </IconButton>
                  </Tooltip>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Dialog for adding/editing candidates */}
      <Dialog open={openDialog} onClose={handleCloseDialog} fullWidth maxWidth="sm">
        <DialogTitle sx={{ backgroundColor: "#007bff", color: "white" }}>
          {currentCandidate.id ? "Edit Candidate" : "Add New Candidate"}
        </DialogTitle>
        <DialogContent sx={{ mt: 3 }}>
          <TextField
            label="Name"
            fullWidth
            value={currentCandidate.name}
            onChange={(e) => setCurrentCandidate({ ...currentCandidate, name: e.target.value })}
            sx={{ mb: 3 }}
          />
          <TextField
            label="Position"
            fullWidth
            value={currentCandidate.position}
            onChange={(e) => setCurrentCandidate({ ...currentCandidate, position: e.target.value })}
            sx={{ mb: 3 }}
          />
          <TextField
            label="Bio"
            fullWidth
            multiline
            rows={3}
            value={currentCandidate.bio}
            onChange={(e) => setCurrentCandidate({ ...currentCandidate, bio: e.target.value })}
            sx={{ mb: 3 }}
          />
          <TextField
            label="Manifesto"
            fullWidth
            multiline
            rows={3}
            value={currentCandidate.manifesto}
            onChange={(e) => setCurrentCandidate({ ...currentCandidate, manifesto: e.target.value })}
            sx={{ mb: 3 }}
          />
          <TextField
            label="Photo URL"
            fullWidth
            value={currentCandidate.photo}
            onChange={(e) => setCurrentCandidate({ ...currentCandidate, photo: e.target.value })}
            sx={{ mb: 3 }}
          />
          <TextField
            label="Video URL"
            fullWidth
            value={currentCandidate.video}
            onChange={(e) => setCurrentCandidate({ ...currentCandidate, video: e.target.value })}
          />
        </DialogContent>
        <DialogActions>
          <Button
            onClick={handleCloseDialog}
            sx={{ color: "#6c757d", "&:hover": { color: "#5a6268" } }}
          >
            Cancel
          </Button>
          <Button
            onClick={handleSaveCandidate}
            variant="contained"
            sx={{ bgcolor: "#28a745", color: "white", "&:hover": { bgcolor: "#218838" } }}
          >
            Save
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ManageCandidates;
